#shard finder
import io
import random
import pyarrow.parquet as pq

from torch.utils.data import IterableDataset, DataLoader, get_worker_info


def find_imagenet_shards(root, split, expected_count):
    paths = sorted(root.rglob(f"{split}-*-of-*.parquet"))

    if not paths:
        raise FileNotFoundError(
            f"No {split} Parquet shards found under {root}"
        )

    names = [path.name for path in paths]

    if len(names) != len(set(names)):
        raise ValueError(
            f"Duplicate {split} shard names found under {root}"
        )

    if len(paths) != expected_count:
        message = (
            f"{split}: found {len(paths)} of "
            f"{expected_count} expected shards."
        )

        if not ALLOW_PARTIAL_IMAGENET:
            raise RuntimeError(message)

        print("PARTIAL DATASET:", message)

    return paths

class BufferedImageNet(IterableDataset):
    """
    Streams ImageNet parquet shards.

    Loads a small pool of shards into RAM while asynchronously
    reading the next pool.

    Returns:
        image: (3, 128, 128)
        label: int
    """

    def __init__(
        self,
        paths,
        transform,
        shards_in_ram=2,
        shuffle=True,
        num_images=None,
    ):
        super().__init__()

        if shards_in_ram < 1:
            raise ValueError("shards_in_ram must be >= 1")

        if num_images is None:
            raise ValueError("num_images must be supplied")

        self.paths = list(paths)
        self.transform = transform
        self.shards_in_ram = shards_in_ram
        self.shuffle = shuffle
        self.num_images = int(num_images)

    def __len__(self):
        return self.num_images

    def __iter__(self):
        from concurrent.futures import ThreadPoolExecutor

        worker = get_worker_info()

        worker_id = worker.id if worker is not None else 0
        num_workers = worker.num_workers if worker is not None else 1

        shared_seed = (
            worker.seed - worker.id
            if worker is not None
            else torch.initial_seed()
        )

        shard_rng = np.random.default_rng(shared_seed)

        shard_order = np.arange(len(self.paths))

        if self.shuffle:
            shard_rng.shuffle(shard_order)

        # Split shards between DataLoader workers
        shard_order = shard_order[worker_id::num_workers]

        rng = np.random.default_rng(
            shared_seed + worker_id
        )

        pools = [
            shard_order[start:start + self.shards_in_ram]
            for start in range(
                0,
                len(shard_order),
                self.shards_in_ram,
            )
        ]

        if not pools:
            return

        def load_pool(pool_ids):
            tables = []

            for shard_id in pool_ids:
                with pq.ParquetFile(
                    self.paths[int(shard_id)]
                ) as parquet:

                    tables.append(
                        parquet.read(
                            columns=["image", "label"],
                            use_threads=False,
                        )
                    )

            return tables

        executor = ThreadPoolExecutor(max_workers=1)

        # Start reading first pool
        pending = executor.submit(
            load_pool,
            pools[0],
        )

        tables = None

        try:
            for pool_index in range(len(pools)):

                # Wait for current pool
                tables = pending.result()
                pending = None

                # Immediately start reading next pool
                if pool_index + 1 < len(pools):
                    pending = executor.submit(
                        load_pool,
                        pools[pool_index + 1],
                    )

                counts = np.array(
                    [table.num_rows for table in tables]
                )

                ends = np.cumsum(counts)

                starts = np.concatenate(
                    ([0], ends[:-1])
                )

                row_order = np.arange(
                    int(ends[-1])
                )

                if self.shuffle:
                    rng.shuffle(row_order)

                try:
                    for pool_row in row_order:

                        table_index = int(
                            np.searchsorted(
                                ends,
                                pool_row,
                                side="right",
                            )
                        )

                        row_index = int(
                            pool_row
                            - starts[table_index]
                        )

                        record = (
                            tables[table_index]["image"][
                                row_index
                            ].as_py()
                        )

                        label = (
                            tables[table_index]["label"][
                                row_index
                            ].as_py()
                        )

                        encoded = record["bytes"]

                        if encoded is None:
                            raise ValueError(
                                "Missing embedded image bytes"
                            )

                        with Image.open(
                            io.BytesIO(encoded)
                        ) as image:

                            full = self.transform(image)

                        yield full, label

                finally:
                    tables.clear()
                    tables = None

        finally:
            if pending is not None:
                pending.cancel()

            executor.shutdown(
                wait=True,
                cancel_futures=True,
            )

            if tables is not None:
                tables.clear()

#define core transformer model (dense or sparse middle)
import math

class CoreTransformer(nn.Module):
    """
    Shallow blocks → middle blocks → fusion → final blocks.

    keep_ratio = 1: plain dense transformer, no fusion layer.
    keep_ratio < 1: in a training step the middle blocks see a
    random keep_ratio share of the tokens (SPRINT sparse middle).

    Tokens are [latent tokens | patch tokens]. The patch count is
    patch_rows * patch_cols; everything before it is latent.
    Reads no globals. Keeps no RoPE cache.
    """

    def __init__(
        self,
        emb_dim,
        num_blocks,
        n_heads,
        head_size,
        keep_ratio=1.0,
        shallow_blocks=1,
        final_blocks=1,
    ):
        super().__init__()

        if not 0 < keep_ratio <= 1:
            raise ValueError("keep_ratio must be in (0, 1].")
        if shallow_blocks < 1 or final_blocks < 1:
            raise ValueError(
                "Need at least one shallow and final block."
            )
        if (
            keep_ratio < 1
            and shallow_blocks + final_blocks >= num_blocks
        ):
            raise ValueError("Need at least one middle block.")

        self.blocks = nn.ModuleList([
            Block(n_heads, head_size, emb_dim)
                for _ in range(num_blocks)
        ])

        self.norm_in = nn.RMSNorm(emb_dim)
        self.norm_out = nn.RMSNorm(emb_dim)

        self.keep_ratio = keep_ratio
        self.shallow_blocks = shallow_blocks
        self.middle_end = num_blocks - final_blocks

        # Set False for full-token training (needs keep_ratio < 1).
        self.sparse_middle = keep_ratio < 1

        if keep_ratio < 1:
            # Fuse shallow and deep features: 2C → C.
            self.fusion = nn.Linear(2 * emb_dim, emb_dim)

            # Start with equal contributions from both paths.
            with torch.no_grad():
                eye = torch.eye(emb_dim)
                self.fusion.weight.copy_(
                    torch.cat((0.5 * eye, 0.5 * eye), dim=1)
                )
                self.fusion.bias.zero_()

        #ROPE frequencies (a constant, not a cache)
        pair_idx = torch.arange(head_size // 4, dtype=torch.float32)
        inv_freq = 100 ** (-pair_idx / (head_size // 4))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def rope_tables(self, patch_rows, patch_cols):
        # Built on every call and returned. Nothing is stored, so a
        # compiled step never guards on a table from the last call.
        device = self.inv_freq.device

        row_pos = (
            2 * torch.arange(
                patch_rows, device=device, dtype=torch.float32
            ) / max(patch_rows - 1, 1) - float(patch_rows > 1)
        ).repeat_interleave(patch_cols)

        col_pos = (
            2 * torch.arange(
                patch_cols, device=device, dtype=torch.float32
            ) / max(patch_cols - 1, 1) - float(patch_cols > 1)
        ).repeat(patch_rows)

        scale = 1.0

        if self.training:
            # Uniform in log-space: shrinking and enlarging balance.
            log_scale = torch.empty(
                (), device=device
            ).uniform_(-math.log(2), math.log(2))

            scale = log_scale.exp()

        row_angles = (
            2 * math.pi * scale
            * row_pos[:, None] * self.inv_freq[None, :]
        )
        col_angles = (
            2 * math.pi * scale
            * col_pos[:, None] * self.inv_freq[None, :]
        )

        return (
            row_angles.cos(),
            row_angles.sin(),
            col_angles.cos(),
            col_angles.sin(),
        )

    @staticmethod
    def gather_tokens(x, indices):
        return x.gather(
            dim=1,
            index=indices.unsqueeze(-1).expand(
                -1, -1, x.shape[-1],
            ),
        )

    @staticmethod
    def gather_rope(rope, indices):
        selected = []
        for table in rope:
            if table.ndim == 2:
                # Shared full-grid table.
                selected.append(table[indices])
            else:
                # Already selected per image by input masking.
                selected.append(
                    table.gather(
                        dim=1,
                        index=indices.unsqueeze(-1).expand(
                            -1, -1, table.shape[-1],
                        ),
                    )
                )
        return tuple(selected)

    @staticmethod
    def sample_indices(batch, count, keep, device):
        # Sort selected indices to preserve original token order.
        return (
            torch.rand(batch, count, device=device)
            .topk(keep, dim=1, largest=False)
            .indices.sort(dim=1)
            .values
        )

    def forward(self, x, patch_rows, patch_cols, time_emb, keep_indices=None):

        x = self.norm_in(x)

        rope = self.rope_tables(patch_rows, patch_cols)

        # Input masking: x already contains only visible patches.
        if keep_indices is not None:
            rope = self.gather_rope(rope, keep_indices)

        B, T, C = x.shape

        # RoPE tells us how many patch tokens are present.
        P = rope[0].shape[-2]

        # Everything before those final patch tokens is latent.
        L = T - P

        assert L >= 0, (
            f"Sequence has {T} total tokens but RoPE contains "
            f"{P} patch positions."
        )

        use_sparse = (
            self.training
            and self.sparse_middle
            and self.keep_ratio < 1
        )

        if not use_sparse and self.keep_ratio == 1:
            # Plain dense transformer.
            for block in self.blocks:
                x = block(x, rope, time_emb)

            return self.norm_out(x)

        # Shallow path sees all available tokens.
        for i in range(self.shallow_blocks):
            x = self.blocks[i](x, rope, time_emb)

        shallow = x

        if use_sparse:
            # Fixed counts. At least one survives in each nonempty
            # group.
            keep_latents = min(L, max(1, int(L * self.keep_ratio)))
            keep_patches = min(P, max(1, int(P * self.keep_ratio)))

            latent_ids = self.sample_indices(
                B, L, keep_latents, x.device,
            )
            patch_ids = self.sample_indices(
                B, P, keep_patches, x.device,
            )

            # Latents remain the prefix; patches follow.
            token_ids = torch.cat(
                (latent_ids, L + patch_ids), dim=1,
            )

            deep = self.gather_tokens(shallow, token_ids)
            middle_rope = self.gather_rope(rope, patch_ids)
        else:
            deep = shallow
            middle_rope = rope

        for i in range(self.shallow_blocks, self.middle_end):
            deep = self.blocks[i](deep, middle_rope, time_emb)

        if use_sparse:
            # Restore deep features to their original positions.
            deep = torch.zeros_like(shallow).scatter(
                dim=1,
                index=token_ids.unsqueeze(-1).expand(-1, -1, C),
                src=deep.to(shallow.dtype),
            )

        x = self.fusion(torch.cat((shallow, deep), dim=-1))

        for i in range(self.middle_end, len(self.blocks)):
            x = self.blocks[i](x, rope, time_emb)

        return self.norm_out(x)

